import { z } from "zod";

/** Ids are UUIDs generated by the database (Prisma `@default(uuid())`). */
export const idSchema = z.uuid("Id không hợp lệ");

/**
 * An amount of money in the currency's smallest unit (VND: dong). Always an integer:
 * money is never a float in this app. Bounded so it survives the trip through JSON numbers.
 */
export const moneySchema = z
  .number("Số tiền phải là số")
  .int("Số tiền phải là số nguyên (đơn vị nhỏ nhất, VND: đồng)")
  .min(Number.MIN_SAFE_INTEGER)
  .max(Number.MAX_SAFE_INTEGER);

/** ISO 4217 code, e.g. "VND", "USD". */
export const currencyCodeSchema = z
  .string()
  .trim()
  .toUpperCase()
  .regex(/^[A-Z]{3}$/, "Mã tiền tệ gồm 3 chữ cái, ví dụ VND");
